end

function UIEntrustQueueCardNode:Refresh(data, entrustId, status, curLevelId)
    if not data then
        return
    end
    self._data = data
    self._status = status
    self._curEntrustId = checkNumber(entrustId)
    self._curLevelId = checkNumber(curLevelId)

    self:FillEntrustTeamMember()
end

function UIEntrustQueueCardNode:FillEntrustTeamMember()
    local dialogs = {}
    local backIsClose = 0
    if self._status == STATUS.TEAMSELECT then
        dialogs = {
            { id = Constants.UITypeIds.UIEntrustTasksDialog}
        }
    elseif self._status == STATUS.ALL then
        backIsClose = 1
    end

    if self._data then 
        local itemGo = self.cardPar.transform:Find("card")
        local cardData = cardComp:GetCardById(self._data.refId)
        --如果没有数据直接隐藏
        if not cardData then
            if itemGo then
                KTool.SetActive(itemGo, false)
            end
        else
            if itemGo then
                CfUtils.RefeshCommonSmallHeroGo(itemGo, cardData, cardHeadScale, function()
                    local isBusy = teamComponent:IsEntrustQueuesBusy(self._curEntrustId)
                    if not isBusy then
                        UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {levelId = self._curLevelId, chooseCardStatu = Constants.ChooseCardStatus.Entrust, entrustId = self._curEntrustId, backIsClose = backIsClose}}, dialogs)
                        if self._status == STATUS.TEAMSELECT then
                            teamComponent:SetLastSelectEntrustQueue(self._curEntrustId)
                        end
                    else
                        GameUtils.Toast(localize("该队员正在委托中"))
                    end
                end)
            else
                if not self._smallCardLoader then
                    self._smallCardLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSmallHeadNode.prefab", nil, true)
                end
                if self._smallCardLoader.IsSuccess then
                    local go = self.cardPar.transform:Find("card")
                    if not go then 
                        go = CfUtils.InstantiateGo(self._smallCardLoader.ResultObject, self.cardPar)
                        go.name = "card"
                    end
                    go.transform.localPosition = Vector3(0, 0, 0)
                    
                    if go then
                        CfUtils.RefeshCommonSmallHeroGo(go, cardData, cardHeadScale, function()
                            local isBusy = teamComponent:IsEntrustQueuesBusy(self._curEntrustId)
                            if not isBusy then
                                UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {levelId = self._curLevelId, chooseCardStatu = Constants.ChooseCardStatus.Entrust, entrustId = self._curEntrustId, backIsClose = backIsClose}}, dialogs)
                                if self._status == STATUS.TEAMSELECT then
                                    teamComponent:SetLastSelectEntrustQueue(self._curEntrustId)
                                end
                            else
                                GameUtils.Toast(localize("该队员正在委托中"))
                            end
                        end)
                    end
                end
            end
        end
    end

    SetButtonAction(self.bg,  function()
        local isBusy = teamComponent:IsEntrustQueuesBusy(self._curEntrustId)
        if not isBusy then
            UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {levelId = self._curLevelId, chooseCardStatu = Constants.ChooseCardStatus.Entrust, entrustId = self._curEntrustId, backIsClose = backIsClose}}, dialogs)
            if self._status == STATUS.TEAMSELECT then
                teamComponent:SetLastSelectEntrustQueue(self._curEntrustId)
            end
        else
            GameUtils.Toast(localize("该队列正在委托中"))
        end
    end)
end

function UIEntrustQueueCardNode:OnDestroy()
    if not isNull(self._smallCardLoader) then
        self._smallCardLoader:Release()
        self._smallCardLoader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIEntrustQueueCardNode
